describe("승인 뒤 화면 변경", () => {
	test("타겟을 바꾸면 서명이 달라지고 폰 파일은 그대로다", () => {
		const { store, phone } = open();
		const approved = store.approve();
		expect(phone.read()).toBeNull();
		store.saveListing("ac", { target: 250_000, until: "2026-11-30" });
		expect(store.signature()).not.toBe(approved.batch.signature);
		expect(phone.read()).toBeNull();
		expect(store.activeBatch()?.id).toBe(approved.batch.id);
	});
});

