describe("끌올 문구 반영", () => {
	const card = {
		title: "3단 책장",
		price: 10_000,
		area: "방배4동",
		postedAgoDays: 3,
		bumpAgoDays: 0,
		bumpAgoMinutes: 725,
		bumpCount: 2,
		views: 61,
		chats: 1,
		hearts: 1,
	};

	test("`끌올 12시간 전`은 분 단위로 되짚어 bumpedAt을 만든다", () => {
		const { store } = open();
		const now = new Date("2026-10-28T10:00:00.000Z");
		store.replaceFromPhone([card], now);
		const shelf = store.listings().find((listing) => listing.id === "shelf");
		expect(shelf?.bumpCount).toBe(2);
		expect(shelf?.bumpedAt).toBe("2026-10-27T21:55:00.000Z");
		expect(Date.parse(shelf?.nextBumpAt ?? "") - Date.parse(shelf?.bumpedAt ?? "")).toBe(72 * 3_600_000);
	});

	test("폰이 보여 준 다음 시각이 추정보다 늦으면 그대로 둔다", () => {
		const { store } = open();
		const observed = new Date(Date.now() + 30 * 86_400_000).toISOString();
		store.recordCooldown("shelf", observed);
		store.replaceFromPhone([card]);
		expect(store.listings().find((listing) => listing.id === "shelf")?.nextBumpAt).toBe(observed);
	});

	test("끌올 문구가 없으면 마지막 시각을 이어 쓴다", () => {
		const { store } = open();
		store.recordBump("shelf", { bumpedAt: "2026-10-28T10:00:00.000Z", bumpCount: 1 });
		store.replaceFromPhone([{ ...card, bumpAgoDays: null, bumpAgoMinutes: null, bumpCount: null }]);
		const shelf = store.listings().find((listing) => listing.id === "shelf");
		expect(shelf?.bumpedAt).toBe("2026-10-28T10:00:00.000Z");
		expect(shelf?.bumpCount).toBe(1);
	});

	test("지난 추정이 새 추정보다 늦어도 지키지 않는다(관측만 지킨다)", () => {
		// 2026-11-11 휘슬러 2단 찜기: 옛 추정 10:52Z 가 남아 10:30Z 회차에서 끌올이 빠졌다.
		const { store } = open();
		const now = new Date("2026-11-11T10:30:00.000Z");
		store.recordBump("shelf", { bumpedAt: "2026-11-07T10:52:55.000Z", bumpCount: 3 });
		const days = { ...card, bumpAgoMinutes: null, bumpAgoDays: 5, bumpCount: 3 };
		store.replaceFromPhone([days], now);
		const shelf = store.listings().find((listing) => listing.id === "shelf");
		expect(shelf?.bumpedAt).toBe("2026-11-06T10:30:00.000Z");
		expect(Date.parse(shelf?.nextBumpAt ?? "")).toBeLessThan(now.getTime());
	});

	test("하루 단위 문구와 맞는 아는 끌올 시각은 그대로 쓴다", () => {
		const { store } = open();
		const now = new Date("2026-11-11T10:30:00.000Z");
		store.recordBump("shelf", { bumpedAt: "2026-11-06T02:00:00.000Z", bumpCount: 3 });
		store.replaceFromPhone([{ ...card, bumpAgoMinutes: null, bumpAgoDays: 5, bumpCount: 3 }], now);
		expect(store.listings().find((listing) => listing.id === "shelf")?.bumpedAt).toBe("2026-11-06T02:00:00.000Z");
	});

	test("관측값보다 늦은 추정이 나오면 추정으로 다시 긋는다", () => {
		const { store } = open();
		const observed = new Date(Date.now() + 3_600_000).toISOString();
		store.recordCooldown("shelf", observed);
		store.replaceFromPhone([{ ...card, bumpCount: 3, bumpAgoMinutes: 10 }]);
		const shelf = store.listings().find((listing) => listing.id === "shelf");
		expect(shelf?.bumpCount).toBe(3);
		expect(Date.parse(shelf?.nextBumpAt ?? "") - Date.parse(shelf?.bumpedAt ?? "")).toBe(96 * 3_600_000);
	});

